import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.HashSet;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int m = Integer.parseInt(st.nextToken());HashSet<Long> set = new HashSet<Long>();st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {set.add(Long.parseLong(st.nextToken()));}StringBuilder sb = new StringBuilder();for (int i = 0; i < m; i++) {long candy = Long.parseLong(st.nextToken());if (set.contains(candy)) {sb.append("YES\n");} else {sb.append("NO\n");set.add(candy);}}System.out.print(sb.toString());}}}